-- In-game text chat between the two players of a room.
-- Clients can only read their own rooms' messages; every write goes through send_message().

create table public.room_messages (
  id          uuid primary key default gen_random_uuid(),
  room_id     uuid not null references public.rooms (id) on delete cascade,
  sender_id   uuid not null references public.players (id) on delete cascade,
  body        text not null check (char_length(body) between 1 and 200),
  -- Generated by the sender's app; makes "tap to retry" idempotent.
  client_id   uuid not null,
  created_at  timestamptz not null default now(),
  unique (sender_id, client_id)
);

create index room_messages_room_created_idx on public.room_messages (room_id, created_at);
create index room_messages_sender_created_idx on public.room_messages (sender_id, created_at);

alter table public.room_messages enable row level security;

create policy "room_messages: members read"
  on public.room_messages for select to authenticated
  using (
    exists (
      select 1 from public.rooms r
      where r.id = room_messages.room_id
        and (select auth.uid()) in (r.player_x, r.player_o)
    )
  );

revoke insert, update, delete on public.room_messages from anon, authenticated;
revoke all on public.room_messages from anon;

-- ---------------------------------------------------------------------------
-- send_message: members only, cleaned text, 1–200 chars, ~5 messages / 10 s.
-- Returns the stored row; re-sending the same client_id returns the original.
-- ---------------------------------------------------------------------------
create or replace function public.send_message(p_room_id uuid, p_body text, p_client_id uuid)
returns public.room_messages
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  r public.rooms;
  clean text;
  result public.room_messages;
begin
  if uid is null then
    raise exception 'NOT_AUTHENTICATED';
  end if;
  if p_client_id is null then
    raise exception 'INVALID_MESSAGE';
  end if;

  -- Lock the room so concurrent sends are counted correctly by the rate limit.
  select * into r from public.rooms where id = p_room_id for update;
  if not found or uid not in (r.player_x, coalesce(r.player_o, r.player_x)) then
    raise exception 'ROOM_NOT_FOUND';
  end if;

  -- Idempotent retry.
  select * into result from public.room_messages where sender_id = uid and client_id = p_client_id;
  if found then
    return result;
  end if;

  if r.status = 'abandoned' then
    raise exception 'ROOM_CLOSED';
  end if;

  -- Strip control characters (keep normal spaces), collapse whitespace runs, trim.
  clean := btrim(regexp_replace(regexp_replace(coalesce(p_body, ''), '[\x00-\x1F\x7F]', ' ', 'g'), '\s+', ' ', 'g'));
  if clean = '' then
    raise exception 'MESSAGE_EMPTY';
  end if;
  if char_length(clean) > 200 then
    raise exception 'MESSAGE_TOO_LONG';
  end if;

  if (select count(*) from public.room_messages
       where sender_id = uid and room_id = r.id and created_at > now() - interval '10 seconds') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  insert into public.room_messages (room_id, sender_id, body, client_id)
  values (r.id, uid, clean, p_client_id)
  returning * into result;
  return result;
end;
$$;

revoke execute on function public.send_message(uuid, text, uuid) from public, anon;
grant  execute on function public.send_message(uuid, text, uuid) to authenticated;

-- Live delivery (Realtime applies the select policy above per subscriber).
alter publication supabase_realtime add table public.room_messages;
